const results = items[0].json.results || [];

const weekMap = {};
const campaignMap = {};

for (const r of results) {
  const week  = r.segments?.week || 'unknown';
  const cost  = Number(r.metrics?.costMicros || 0) / 1000000;
  const impr  = Number(r.metrics?.impressions || 0);
  const clks  = Number(r.metrics?.clicks || 0);
  const conv  = Number(r.metrics?.conversions || 0);

  if (!weekMap[week]) weekMap[week] = { week_start: week, spend: 0, impressions: 0, clicks: 0, conversions: 0 };
  weekMap[week].spend       += cost;
  weekMap[week].impressions += impr;
  weekMap[week].clicks      += clks;
  weekMap[week].conversions += conv;

  const cId   = String(r.campaign?.id || '');
  const cName = r.campaign?.name || 'Unknown';
  if (!campaignMap[cId]) campaignMap[cId] = { campaign_id: cId, campaign_name: cName, spend: 0, impressions: 0, clicks: 0, conversions: 0 };
  campaignMap[cId].spend       += cost;
  campaignMap[cId].impressions += impr;
  campaignMap[cId].clicks      += clks;
  campaignMap[cId].conversions += conv;
}

const weekly = Object.values(weekMap)
  .sort((a, b) => a.week_start.localeCompare(b.week_start))
  .map(w => ({
    ...w,
    spend: Number(w.spend.toFixed(2)),
    ctr:   w.impressions > 0 ? Number((w.clicks / w.impressions * 100).toFixed(4)) : 0,
    cpl:   w.conversions > 0 ? Number((w.spend  / w.conversions).toFixed(2))       : null
  }));

const totals = weekly.reduce((a, w) => ({
  spend:       a.spend       + w.spend,
  impressions: a.impressions + w.impressions,
  clicks:      a.clicks      + w.clicks,
  conversions: a.conversions + w.conversions
}), { spend: 0, impressions: 0, clicks: 0, conversions: 0 });
totals.spend = Number(totals.spend.toFixed(2));
totals.ctr   = totals.impressions > 0 ? Number((totals.clicks / totals.impressions * 100).toFixed(4)) : 0;
totals.cpl   = totals.conversions > 0 ? Number((totals.spend  / totals.conversions).toFixed(2))       : null;

const topCampaigns = Object.values(campaignMap)
  .sort((a, b) => b.spend - a.spend).slice(0, 5)
  .map(c => ({
    ...c,
    spend: Number(c.spend.toFixed(2)),
    ctr:   c.impressions > 0 ? Number((c.clicks / c.impressions * 100).toFixed(4)) : 0,
    cpl:   c.conversions > 0 ? Number((c.spend  / c.conversions).toFixed(2))       : null
  }));

const accountName = results[0]?.customer?.descriptiveName || 'Springfield';

return [{ json: { current_weekly: weekly, current_totals: totals, current_top_campaigns: topCampaigns, account_name: accountName } }];

