const now = new Date();
const m = now.getMonth();
const y = now.getFullYear();
const qi = Math.floor(m / 3);

const qStarts   = [0, 3, 6, 9];
const qEnds     = [2, 5, 8, 11];
const qLastDays = [31, 30, 30, 31];

const cqs = new Date(y, qStarts[qi], 1).toISOString().split('T')[0];
const cqe = new Date(y, qEnds[qi], qLastDays[qi]).toISOString().split('T')[0];

const pqi = qi === 0 ? 3 : qi - 1;
const py  = qi === 0 ? y - 1 : y;
const pqs = new Date(py, qStarts[pqi], 1).toISOString().split('T')[0];
const pqe = new Date(py, qEnds[pqi], qLastDays[pqi]).toISOString().split('T')[0];

return [{
  json: {
    current_q_start: cqs,
    current_q_end:   cqe,
    prev_q_start:    pqs,
    prev_q_end:      pqe,
    quarter:         'Q' + (qi + 1),
    year:            y,
    prev_quarter:    'Q' + (pqi + 1),
    prev_year:       py
  }
}];

